// Agente especialista en n8n. Habla A2A (JSON-RPC 2.0) igual que el
// especialista LangGraph: recibe un `message/send` y devuelve un artefacto.
const entrada = $input.first().json;
const body = entrada.body ?? entrada;
const id = body?.id ?? null;

const texto = (body?.params?.message?.parts ?? [])
  .filter((parte) => parte.kind === 'text')
  .map((parte) => parte.text)
  .join('\n');

// El agente principal manda el encargo en lenguaje natural y, aparte, los
// parámetros ya resueltos por su LLM. n8n no necesita modelo propio: calcula.
const bloque = texto.match(/\{[\s\S]*\}/);
if (!bloque) {
  return [{ json: { jsonrpc: '2.0', id, error: { code: -32602, message: 'Faltan parámetros del plan' } } }];
}

let p;
try {
  p = JSON.parse(bloque[0]);
} catch (e) {
  return [{ json: { jsonrpc: '2.0', id, error: { code: -32602, message: 'Parámetros inválidos' } } }];
}

const monto = Number(p.monto_usd);
const semanas = Number(p.semanas);
const valido = Number.isFinite(monto) && monto > 0 && monto <= 1000000
  && Number.isInteger(semanas) && semanas >= 1 && semanas <= 104;
if (!valido) {
  return [{ json: { jsonrpc: '2.0', id, error: { code: -32602, message: 'monto_usd o semanas fuera de rango' } } }];
}

const plan = [];
let acumulado = 0;
for (let i = 1; i <= semanas; i++) {
  acumulado = Math.round((acumulado + monto) * 100) / 100;
  plan.push({ numero: i, monto_usd: monto, acumulado_usd: acumulado });
}

const artefacto = {
  tipo: 'plan_dca',
  cripto: String(p.cripto ?? 'bitcoin').toLowerCase(),
  monto_usd: monto,
  frecuencia: String(p.frecuencia ?? 'semanal'),
  semanas,
  compras: semanas,
  total_usd: acumulado,
  plan,
  nota: 'Plan de práctica. No es asesoría financiera ni una orden de compra.',
};

return [{ json: {
  jsonrpc: '2.0',
  id,
  result: {
    kind: 'task',
    id: 'n8n-' + (body?.params?.message?.messageId ?? Date.now()),
    status: { state: 'completed' },
    artifacts: [
      { artifactId: 'plan-dca', parts: [{ kind: 'text', text: JSON.stringify(artefacto) }] },
    ],
  },
} }];
